import { useEffect, useRef, useState } from "react";
import OptionsContainer from "./components/OptionsContainer";
import Minimap from "./components/MinimapContainer/MinimapContainer";
import {
  queryAllChatElements,
  queryChatContainer,
  queryNavElement,
} from "./utils/renderLogic";

export default function App() {
  const [showMinimap, setShowMinimap] = useState<boolean>(false);
  const [manualRefresh, setManualRefresh] = useState<boolean>(false);
  const chatContainer = useRef<HTMLElement | null>(null);
  const scrollContainer = useRef<HTMLElement | null>(null);

  function triggerCanvasRefresh() {
    // changing state always triggers a refresh of parent and child states (excluding memo compnents)
    // console.log("manual refresh triggered")
    setManualRefresh((temp) => !temp);
    chatContainer.current = queryChatContainer()
    if (chatContainer.current) {
      scrollContainer.current = chatContainer.current.parentElement;
    }
  }

  // Run when mounted
  useEffect(() => {
    addLocationObserver(() => {
      // console.log("document body changed");
      setTimeout(() => {
        const newChat = queryChatContainer();
        if (chatContainer.current !== newChat) {
          // console.log("chat container changed");
          triggerCanvasRefresh();
        }
        chatContainer.current = newChat;
        if (newChat) {
          scrollContainer.current = newChat.parentElement;
        }
      }, 500); // delayed because it takes some time for chats  to load
    });
  }, []);

  const onToggleMinimap = () => {
    setShowMinimap(!showMinimap);
    triggerCanvasRefresh();
  };
  const onRefreshMinimap = () => {
    triggerCanvasRefresh();
  };

  return (
    <div className="app-container" style={appContainerStyle}>
      <OptionsContainer
        onToggleMinimap={onToggleMinimap}
        onRefreshMinimap={onRefreshMinimap}
        onNextChat={() => onNextChat(scrollContainer.current)}
        onPreviousChat={() => onPreviousChat(scrollContainer.current)}
        showMinimap={showMinimap}
      />
      {showMinimap ? (
        <Minimap
          refreshMinimap={manualRefresh}
          chatContainer={chatContainer.current}
          scrollContainer={scrollContainer.current}
        />
      ) : null}
    </div>
  );
}

const appContainerStyle: React.CSSProperties = {
  display: "flex",
  height: "100%",
  width: "100%",
  overflow: "hidden",
  justifyContent: "right",
  pointerEvents: "none",
  userSelect: "none",
};
function addLocationObserver(callback: MutationCallback) {
  // Options for the observer (which mutations to observe)
  const config = { attributes: false, childList: true, subtree: false };

  // Create an observer instance linked to the callback function
  const observer = new MutationObserver(callback);

  // Start observing the target node for configured mutations
  observer.observe(document.body, config);
}

const onNextChat = (scrollContainer: HTMLElement | null) => {
  const navElement = queryNavElement();
  if (!scrollContainer || !navElement) return;
  const navHeight = navElement.offsetHeight;
  const chatElements = queryAllChatElements();
  const nextChats = chatElements.filter((element) => {
    return element.getBoundingClientRect().top > 1.1 * navHeight;
  });
  if (nextChats.length === 0) return;
  const firstNextChat = nextChats[0];
  scrollContainer.scrollTo({
    top:
      scrollContainer.scrollTop +
      firstNextChat.getBoundingClientRect().top -
      navHeight,
    behavior: "smooth",
  });
};
const onPreviousChat = (scrollContainer: HTMLElement | null) => {
  const navElement = queryNavElement();
  if (!scrollContainer || !navElement) return;
  const navHeight = navElement.offsetHeight;
  const chatElements = queryAllChatElements();
  const nextChats = chatElements.filter((element) => {
    return element.getBoundingClientRect().top < navHeight;
  });
  if (nextChats.length === 0) return;
  const firstNextChat = nextChats[nextChats.length - 1];
  scrollContainer.scrollTo({
    top:
      scrollContainer.scrollTop +
      firstNextChat.getBoundingClientRect().top -
      navHeight,
    behavior: "smooth",
  });
};

import { memo, useEffect, useRef } from "react";
import { generateMinimapCanvas } from "../../../utils/renderLogic";

interface CanvasContainerProps {
  refreshCanvas: boolean;
  setScale: CallableFunction;
  chatContainer: HTMLElement | null;
}

const CanvasContainer = ({
  refreshCanvas,
  setScale,
  chatContainer,
}: CanvasContainerProps) => {
  const canvasContainerRef = useRef<HTMLDivElement>(null);
  const isLoading = useRef<boolean>(false)

  // useEffect(()=> console.log("canvas container rerendered", isLoading.current, chatContainer===null))

  useEffect(() => {
    if (isLoading.current===true) return 
    (async () => {
      const canvasContainer = canvasContainerRef.current;
      if (!canvasContainer) return;
      if (canvasContainer.parentElement){ // scroll to top to display message
        canvasContainer.parentElement.scrollTo(0, 0)
      }
      if (!chatContainer) {
        canvasContainer.innerHTML = "No chat detected, try refreshing the minimap"
        return
      }
      isLoading.current = true
      // console.log("generating minmiap canvas...")
      canvasContainer.innerHTML = "loading.."
      const canvas = await generateMinimapCanvas(chatContainer);
      isLoading.current = false
      canvasContainer.innerHTML = "";
      canvasContainer.appendChild(canvas);

      const scale = canvasContainer.offsetWidth / canvas.offsetWidth;
      canvas.style.width = `${canvasContainer.offsetWidth}px`;
      canvas.style.height = `${scale * canvas.offsetHeight}px`;
      setScale(scale);
    })();
  }, [refreshCanvas, setScale, chatContainer]);


  return (
    <div
      className="canvas-container"
      style={canvasContainerStyle}
      ref={canvasContainerRef}
    ></div>
  );
};

const canvasContainerStyle: React.CSSProperties = {
  width: "100%",
  color: "white",
  fontWeight: "bold"
};

export default memo(CanvasContainer);

import React, { useEffect, useRef, useState } from "react";
import ViewOverlay from "./ViewOverlay/ViewOverlay";
import CanvasContainer from "./CanvasContainer/CanvasContainer";

interface MinimapProps {
  refreshMinimap: boolean;
  chatContainer: HTMLElement | null;
  scrollContainer: HTMLElement | null;
}
const MinimapContainer = ({
  refreshMinimap,
  chatContainer,
  scrollContainer,
}: MinimapProps) => {
  const [scale, setScale] = useState<number>(0);
  const mouseDown = useRef<boolean>(false);
  const [dragPos, setDragPos] = useState<number>(0);
  const minimapContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const minimapContainer = minimapContainerRef.current;
    if (!minimapContainer) return;
    // console.log("event listeners added.");
    window.addEventListener("mouseup", () => {
      mouseDown.current = false;
    });
    minimapContainer.addEventListener("mousedown", () => {
      mouseDown.current = true;
    });
    minimapContainer.addEventListener("mousemove", (e) => {
      if (mouseDown.current) {
        setDragPos(e.clientY);
      }
    });
  }, [setDragPos]);

  useEffect(() => {
    const minimapContainer = minimapContainerRef.current;
    if (!minimapContainer) return;
    if (!scrollContainer) return;
    onDrag(minimapContainer, scrollContainer, scale, dragPos);
  }, [dragPos, scrollContainer, scale]);

  useEffect(() => {
    const minimapContainer = minimapContainerRef.current;
    if (!scrollContainer) return;
    if (!minimapContainer) return;
    scrollContainer.addEventListener("scroll", () =>
      onScroll(minimapContainer, scrollContainer, scale)
    );
  }, [refreshMinimap, scale, scrollContainer]);

  return (
    <div
      className="minimap-container"
      style={minimapContainerStyle}
      ref={minimapContainerRef}
    >
      <CanvasContainer
        refreshCanvas={refreshMinimap}
        chatContainer={chatContainer}
        setScale={setScale}
      />
      <ViewOverlay
        refreshCanvas={refreshMinimap}
        scrollContainer={scrollContainer}
        scale={scale}
      />
    </div>
  );
};

const minimapContainerStyle: React.CSSProperties = {
  position: "relative",
  width: "80px",
  height: "90vh",
  backgroundColor: "#343442",
  pointerEvents: "all",
  boxShadow: "0 0 20px rgba(0, 0, 0, 1)",
  overflowY: "scroll",
  scrollbarWidth: "none",
};

export default MinimapContainer;

function onDrag(
  minimapContainer: HTMLElement,
  scrollContainer: HTMLElement,
  scale: number,
  mousePos: number
) {
  const relativeMousePos =
    mousePos - minimapContainer.getBoundingClientRect().top;
  const newScrollPos =
    (relativeMousePos + minimapContainer.scrollTop) / scale -
    0.5 * scrollContainer.offsetHeight;

  scrollContainer.scrollTo(0, newScrollPos);
}

function onScroll(
  minimapContainer: HTMLElement,
  scrollContainer: HTMLElement,
  scale: number
) {
  const ratio =
    scrollContainer.scrollTop /
    (scrollContainer.scrollHeight + scrollContainer.offsetHeight);

  minimapContainer.scrollTop =
    scale * scrollContainer.scrollTop - ratio * minimapContainer.offsetHeight;
}

import { useEffect, useState } from "react";

interface ViewOverLayProps {
  refreshCanvas: boolean;
  scale: number;
  scrollContainer: HTMLElement | null;
}

const ViewOverlay = ({
  refreshCanvas,
  scale,
  scrollContainer,
}: ViewOverLayProps) => {
  const [scrollTop, setScrollTop] = useState(0);
  const [height, setHeight] = useState(0);

  function onScroll(scrollContainer: HTMLElement, scale: number) {
    setScrollTop(scrollContainer.scrollTop * scale);
    setHeight(scrollContainer.offsetHeight * scale);
  }

  useEffect(() => {
    if (!scrollContainer) return;
    onScroll(scrollContainer, scale);
    scrollContainer.addEventListener("scroll", (event) => {
      if (!(event.target instanceof HTMLElement)) return;
      onScroll(event.target, scale);
    });
  }, [scale, refreshCanvas, scrollContainer]);

  const currentViewStyle: React.CSSProperties = {
    position: "absolute",
    top: `${scrollTop}px`,
    left: "0",
    width: "100%",
    height: `${height}px`,
    backgroundColor: `#00FFD744`,
    cursor: "grab",
  };
  return <div className="current-view" style={currentViewStyle}></div>;
};

export default ViewOverlay;

